function inicializarFormulario(){const e=document.querySelector("#formCadastro");if(!e)return;const t=document.querySelector("#nome"),o=document.querySelector("#cpf"),i=document.querySelector("#telefone"),r=document.querySelector("#cep"),a=document.querySelector("#email"),l=document.querySelector("#mensagem"),n=document.querySelector("#erroNome"),u=document.querySelector("#erroCpf"),c=document.querySelector("#erroTelefone"),s=document.querySelector("#erroCep"),d=document.querySelector("#erroEmail"),m=localStorage.getItem("cadastroPatinhas");if(m)try{const e=JSON.parse(m);t.value=e.nome;a.value=e.email}catch(v){localStorage.removeItem("cadastroPatinhas")}e.addEventListener("submit",m=>{m.preventDefault();if(t.validity.valid){n.textContent="";t.removeAttribute("aria-invalid")}else n.textContent="Digite seu nome completo.";if(o.validity.valid){u.textContent="";o.removeAttribute("aria-invalid")}else{u.textContent="Digite um CPF válido. Exemplo: 123.456.789-00";o.setAttribute("aria-invalid","true")}if(i.validity.valid){c.textContent="";i.removeAttribute("aria-invalid")}else c.textContent="Digite um telefone válido. Exemplo: (21)99999-9999";if(r.validity.valid){s.textContent="";r.removeAttribute("aria-invalid")}else{s.textContent="Digite um CEP válido. Exemplo: 20000-000";r.setAttribute("aria-invalid","true")}if(a.validity.valid){d.textContent="";a.removeAttribute("aria-invalid")}else{d.textContent="Digite um e-mail válido.";a.setAttribute("aria-invalid","true")}if(e.checkValidity()){const n={nome:t.value,cpf:o.value,telefone:i.value,cep:r.value,email:a.value};localStorage.setItem("cadastroPatinhas",JSON.stringify(n));console.log(n);l.textContent="✅ Cadastro realizado com sucesso!";l.classList.add("sucesso");l.classList.remove("erro");e.reset()}else{l.textContent="❌ Verifique os dados informados.";l.classList.add("erro");l.classList.remove("sucesso")}})}